// Lessons shared by 4.º ESO Matemáticas A and B (the B option adds harder variants).
import type { LessonContent } from './types';
import { glesson as G, L, lesson, M, mix, Nq, q, TF } from './lib';
import { histogram, loops, nim, orderOps, pieChart, relFreq, robot, scale, areaUnits, compositeArea, circle } from './gens';
import { absRelError, algFractions, combinatorics, compoundProb, condProb, eventOps, expGrowth, fracExponent, fracOps, graphRead, inequality, interest, intervals, irrational, linearFn, logs, pctMultiplier, polyOps, powerRules, pythagoras, quadraticFn, radians, regression, roots, sciNotation, sequenceEso, solids, spread, systemsEq, transform, trig, trigSolve, vectorsLines } from './gensEso';

export const reals = G(['Los números reales son los racionales (se pueden escribir como fracción) y los irracionales (infinitas cifras sin periodo, como √2 o π). Todos tienen su lugar en la recta.|Els nombres reals són els racionals (es poden escriure com a fracció) i els irracionals (infinites xifres sense període, com √2 o π). Tots tenen el seu lloc en la recta.|Real numbers are the rationals (can be written as fractions) and the irrationals (endless non-repeating decimals such as √2 or π). They all have a place on the number line.', 'Los intervalos describen trozos de la recta: [a, b] incluye los extremos; (a, b) no.|Els intervals descriuen trossos de la recta: [a, b] inclou els extrems; (a, b) no.|Intervals describe sections of the line: [a, b] includes the ends; (a, b) does not.'],
  '¿Es 0,121212… racional?|És 0,121212… racional?|Is 0.121212… rational?', ['Tiene un periodo (12) que se repite.|Té un període (12) que es repetix.|It has a repeating block (12).', 'Sí: 12/99 = 4/33.|Sí: 12/99 = 4/33.|Yes: 12/99 = 4/33.'], mix(irrational(), intervals(), roots(['between'])));
export const powersRadicals = G(['Las potencias de exponente fraccionario son raíces: a^(m/n) = ⁿ√(aᵐ). Las propiedades de las potencias valen también para los radicales.|Les potències d’exponent fraccionari són arrels: a^(m/n) = ⁿ√(aᵐ). Les propietats de les potències valen també per als radicals.|Fractional powers are roots: a^(m/n) = ⁿ√(aᵐ). The rules of powers also work for surds.', 'Para sumar radicales, primero simplifícalos y suma solo los semejantes.|Per a sumar radicals, primer simplifica’ls i suma només els semblants.|To add surds, simplify them first and add only like surds.'],
  '√12 + √27 = ?|√12 + √27 = ?|√12 + √27 = ?', ['√12 = 2√3; √27 = 3√3.|√12 = 2√3; √27 = 3√3.|√12 = 2√3; √27 = 3√3.', '5√3.|5√3.|5√3.'], mix(roots(['simplify', 'ops', 'cbrt']), fracExponent(), powerRules(true)));
export const sci = G(['Notación científica: a · 10ⁿ con 1 ≤ a < 10. Para operar: multiplica o divide las partes decimales y suma o resta los exponentes; para sumar, iguala primero los exponentes.|Notació científica: a · 10ⁿ amb 1 ≤ a < 10. Per a operar: multiplica o dividix les parts decimals i suma o resta els exponents; per a sumar, iguala primer els exponents.|Standard form: a × 10ⁿ with 1 ≤ a < 10. To calculate: multiply or divide the numbers and add or subtract the powers; to add, make the powers equal first.'],
  '(6 · 10⁸) : (2 · 10³) = ?|(6 · 10⁸) : (2 · 10³) = ?|(6 × 10⁸) ÷ (2 × 10³) = ?', ['6 : 2 = 3.|6 : 2 = 3.|6 ÷ 2 = 3.', '10⁸⁻³ = 10⁵ → 3 · 10⁵.|10⁸⁻³ = 10⁵ → 3 · 10⁵.|10⁸⁻³ = 10⁵ → 3 × 10⁵.'], sciNotation());
export const combined = G(['Operaciones combinadas: paréntesis, potencias y raíces, productos y cocientes, sumas y restas. Con fracciones y signos, ve paso a paso.|Operacions combinades: parèntesis, potències i arrels, productes i quocients, sumes i restes. Amb fraccions i signes, ves pas a pas.|Combined operations: brackets, powers and roots, multiplication and division, addition and subtraction. With fractions and signs, go step by step.'],
  '(−2)³ + 3 · (1 − 4) = ?|(−2)³ + 3 · (1 − 4) = ?|(−2)³ + 3 × (1 − 4) = ?', ['(−2)³ = −8; 1 − 4 = −3.|(−2)³ = −8; 1 − 4 = −3.|(−2)³ = −8; 1 − 4 = −3.', '−8 + (−9) = −17.|−8 + (−9) = −17.|−8 + (−9) = −17.'], mix(orderOps(15), fracOps(['+', '−', '×', '÷'], true)));
export const percents = G(['Índice de variación: aumento del p % → × (1 + p/100); descuento → × (1 − p/100). Para encadenar cambios, multiplica los índices. Para saber el precio inicial, divide por el índice.|Índex de variació: augment del p % → × (1 + p/100); descompte → × (1 − p/100). Per a encadenar canvis, multiplica els índexs. Per a saber el preu inicial, dividix per l’índex.|Multiplier: an increase of p% → × (1 + p/100); a discount → × (1 − p/100). For several changes, multiply the multipliers. To find the original price, divide by the multiplier.', 'El IVA general en España es del 21 %.|L’IVA general a Espanya és del 21 %.|The standard VAT rate in Spain is 21%.'],
  'Con IVA (21 %) un móvil cuesta 242 €. ¿Precio sin IVA?|Amb IVA (21 %) un mòbil costa 242 €. Preu sense IVA?|With 21% VAT a phone costs €242. Price without VAT?', ['Índice: 1,21.|Índex: 1,21.|Multiplier: 1.21.', '242 : 1,21 = 200 €.|242 : 1,21 = 200 €.|242 ÷ 1.21 = €200.'], mix(pctMultiplier(), (r) => { const base = [100, 200, 300, 400, 500][Math.floor(r() * 5)]; const withVat = base * 1.21;
    return Nq(`Con IVA del 21 % un producto cuesta ${String(withVat).replace('.', ',')} €. ¿Cuánto cuesta sin IVA?|Amb IVA del 21 % un producte costa ${String(withVat).replace('.', ',')} €. Quant costa sense IVA?|With 21% VAT a product costs €${withVat}. How much is it without VAT?`, base, [Math.round(withVat * 0.79), Math.round(withVat - 21), base + 21], 'Divide entre 1,21.|Dividix entre 1,21.|Divide by 1.21.'); }));
export const simpleInterest = G(['Interés simple: el interés de cada año es el mismo. I = C · i · t / 100. Capital final = C + I.|Interés simple: l’interés de cada any és el mateix. I = C · i · t / 100. Capital final = C + I.|Simple interest: the interest is the same every year. I = P × r × t ÷ 100. Final amount = P + I.'],
  '2 000 € al 4 % durante 3 años.|2 000 € al 4 % durant 3 anys.|€2,000 at 4% for 3 years.', ['I = 2 000 · 4 · 3 / 100 = 240 €.|I = 2 000 · 4 · 3 / 100 = 240 €.|I = 2,000 × 4 × 3 ÷ 100 = €240.', 'Capital final: 2 240 €.|Capital final: 2 240 €.|Final amount: €2,240.'], interest(false));
export const compoundInterest = G(['Interés compuesto: los intereses se suman al capital y también generan intereses. Cf = C · (1 + i/100)ᵗ.|Interés compost: els interessos se sumen al capital i també generen interessos. Cf = C · (1 + i/100)ᵗ.|Compound interest: the interest is added to the amount and earns interest too. Final = P × (1 + r/100)ᵗ.'],
  '1 000 € al 10 % compuesto durante 2 años.|1 000 € al 10 % compost durant 2 anys.|€1,000 at 10% compound for 2 years.', ['1 000 · 1,1² = 1 000 · 1,21.|1 000 · 1,1² = 1 000 · 1,21.|1,000 × 1.1² = 1,000 × 1.21.', '1 210 €.|1 210 €.|€1,210.'], mix(interest(true), interest(false)));
export const logarithms = G(['El logaritmo en base b de x es el exponente al que hay que elevar b para obtener x: log_b x = y ⇔ bʸ = x.|El logaritme en base b de x és l’exponent al qual cal elevar b per a obtindre x: log_b x = y ⇔ bʸ = x.|The logarithm base b of x is the power b must be raised to to give x: log_b x = y ⇔ bʸ = x.', 'Propiedades: log(a · c) = log a + log c; log(aⁿ) = n · log a.|Propietats: log(a · c) = log a + log c; log(aⁿ) = n · log a.|Rules: log(a × c) = log a + log c; log(aⁿ) = n × log a.'],
  'log₂ 32 = ?|log₂ 32 = ?|log₂ 32 = ?', ['2 elevado a qué da 32: 2⁵ = 32.|2 elevat a què dona 32: 2⁵ = 32.|2 to what power is 32? 2⁵ = 32.', 'log₂ 32 = 5.|log₂ 32 = 5.|log₂ 32 = 5.'], logs());
export const sequences = G(['Aritmética: aₙ = a₁ + (n − 1)d; suma de n términos Sₙ = (a₁ + aₙ) · n / 2. Geométrica: aₙ = a₁ · rⁿ⁻¹.|Aritmètica: aₙ = a₁ + (n − 1)d; suma de n termes Sₙ = (a₁ + aₙ) · n / 2. Geomètrica: aₙ = a₁ · rⁿ⁻¹.|Arithmetic: aₙ = a₁ + (n − 1)d; sum of n terms Sₙ = (a₁ + aₙ) × n ÷ 2. Geometric: aₙ = a₁ × rⁿ⁻¹.'],
  'Suma de los 10 primeros términos de 1, 3, 5, 7…|Suma dels 10 primers termes d’1, 3, 5, 7…|Sum of the first 10 terms of 1, 3, 5, 7…', ['a₁₀ = 1 + 9 · 2 = 19.|a₁₀ = 1 + 9 · 2 = 19.|a₁₀ = 1 + 9 × 2 = 19.', 'S = (1 + 19) · 10 / 2 = 100.|S = (1 + 19) · 10 / 2 = 100.|S = (1 + 19) × 10 ÷ 2 = 100.'], mix(sequenceEso(), (r) => { const a1 = 1 + Math.floor(r() * 6), d = 1 + Math.floor(r() * 5), n = 5 + Math.floor(r() * 8); const an = a1 + (n - 1) * d, S = ((a1 + an) * n) / 2;
    return Nq(`Progresión aritmética con a₁ = ${a1} y d = ${d}. ¿Cuánto suman los ${n} primeros términos?|Progressió aritmètica amb a₁ = ${a1} i d = ${d}. Quant sumen els ${n} primers termes?|Arithmetic sequence with a₁ = ${a1} and d = ${d}. What is the sum of the first ${n} terms?`, S, [an * n, S + an, (a1 + an) * n], 'Calcula aₙ y aplica Sₙ = (a₁ + aₙ) · n / 2.|Calcula aₙ i aplica Sₙ = (a₁ + aₙ) · n / 2.|Find aₙ and use Sₙ = (a₁ + aₙ) × n ÷ 2.'); }));
export const polyIdent = G(['Opera polinomios agrupando términos semejantes. Identidades notables: (a ± b)² = a² ± 2ab + b²; (a + b)(a − b) = a² − b².|Opera polinomis agrupant termes semblants. Identitats notables: (a ± b)² = a² ± 2ab + b²; (a + b)(a − b) = a² − b².|Work with polynomials by collecting like terms. Special products: (a ± b)² = a² ± 2ab + b²; (a + b)(a − b) = a² − b².'],
  '(2x + 3)² = ?|(2x + 3)² = ?|(2x + 3)² = ?', ['(2x)² + 2 · 2x · 3 + 3².|(2x)² + 2 · 2x · 3 + 3².|(2x)² + 2 × 2x × 3 + 3².', '4x² + 12x + 9.|4x² + 12x + 9.|4x² + 12x + 9.'], polyOps(['add', 'mul', 'identity']));
export const valueRoots = G(['El valor numérico P(a) se obtiene sustituyendo x por a. Si P(a) = 0, a es una raíz. Teorema del resto: el resto de dividir P(x) entre (x − a) es P(a).|El valor numèric P(a) s’obté substituint x per a. Si P(a) = 0, a és una arrel. Teorema del residu: el residu de dividir P(x) entre (x − a) és P(a).|The value P(a) comes from replacing x with a. If P(a) = 0, a is a root. Remainder theorem: the remainder of P(x) ÷ (x − a) is P(a).'],
  '¿Es 2 raíz de x² − 5x + 6?|És 2 arrel de x² − 5x + 6?|Is 2 a root of x² − 5x + 6?', ['P(2) = 4 − 10 + 6.|P(2) = 4 − 10 + 6.|P(2) = 4 − 10 + 6.', '= 0: sí, es raíz.|= 0: sí, és arrel.|= 0: yes, it is a root.'], polyOps(['value', 'root', 'ruffini']));
export const factorise = G(['Factorizar es escribir un polinomio como producto. Pasos: saca factor común, busca identidades notables y busca raíces (Ruffini o fórmula de 2.º grado).|Factoritzar és escriure un polinomi com a producte. Passos: trau factor comú, busca identitats notables i busca arrels (Ruffini o fórmula de 2n grau).|Factorising writes a polynomial as a product. Steps: take out a common factor, look for special products and find roots (synthetic division or the quadratic formula).'],
  'x² − 7x + 10 = ?|x² − 7x + 10 = ?|x² − 7x + 10 = ?', ['Raíces: dos números que sumen 7 y multipliquen 10: 2 y 5.|Arrels: dos nombres que sumen 7 i multipliquen 10: 2 i 5.|Roots: two numbers adding to 7 and multiplying to 10: 2 and 5.', '(x − 2)(x − 5).|(x − 2)(x − 5).|(x − 2)(x − 5).'], polyOps(['factor', 'identity', 'root']));
export const algFrac = G(['Una fracción algebraica es un cociente de polinomios. Para simplificar, factoriza numerador y denominador y tacha los factores comunes.|Una fracció algebraica és un quocient de polinomis. Per a simplificar, factoritza numerador i denominador i ratlla els factors comuns.|An algebraic fraction is one polynomial divided by another. To simplify, factorise top and bottom and cancel common factors.'],
  '(x² − 9) / (x − 3) = ?|(x² − 9) / (x − 3) = ?|(x² − 9) ÷ (x − 3) = ?', ['x² − 9 = (x + 3)(x − 3).|x² − 9 = (x + 3)(x − 3).|x² − 9 = (x + 3)(x − 3).', 'Tacho (x − 3): queda x + 3.|Ratlle (x − 3): queda x + 3.|Cancel (x − 3): x + 3.'], mix(algFractions(), polyOps(['factor'])));
export const systems = G(['Un sistema de dos ecuaciones lineales se resuelve por sustitución, igualación o reducción. Gráficamente, la solución es el punto de corte de dos rectas.|Un sistema de dues equacions lineals es resol per substitució, igualació o reducció. Gràficament, la solució és el punt de tall de dues rectes.|Two linear equations are solved by substitution, equating or elimination. On a graph, the solution is where the two lines meet.'],
  'Entradas: 2 de adulto y 3 de niño cuestan 31 €; 1 de adulto y 1 de niño, 13 €. ¿Precio de la de adulto?|Entrades: 2 d’adult i 3 de xiquet costen 31 €; 1 d’adult i 1 de xiquet, 13 €. Preu de la d’adult?|Tickets: 2 adult and 3 child cost €31; 1 adult and 1 child cost €13. Adult price?', ['2a + 3n = 31; a + n = 13 → a = 13 − n.|2a + 3n = 31; a + n = 13 → a = 13 − n.|2a + 3c = 31; a + c = 13 → a = 13 − c.', '26 − 2n + 3n = 31 → n = 5, a = 8 €.|26 − 2n + 3n = 31 → n = 5, a = 8 €.|26 − 2c + 3c = 31 → c = 5, a = €8.'], systemsEq());
export const inequalities = G(['Una inecuación se resuelve como una ecuación, pero si multiplicas o divides por un número negativo, el signo de la desigualdad cambia de sentido. La solución es un intervalo.|Una inequació es resol com una equació, però si multipliques o dividixes per un nombre negatiu, el signe de la desigualtat canvia de sentit. La solució és un interval.|An inequality is solved like an equation, but if you multiply or divide by a negative number, the inequality sign flips. The solution is an interval.'],
  '−2x + 4 < 10|−2x + 4 < 10|−2x + 4 < 10', ['−2x < 6.|−2x < 6.|−2x < 6.', 'Divido entre −2 y cambia: x > −3.|Dividisc entre −2 i canvia: x > −3.|Divide by −2 and flip: x > −3.'], mix(inequality(), intervals()));
export const errorUnits = G(['Error absoluto = |real − aproximado|; error relativo = error absoluto ÷ real. Para cambiar de unidades usa factores de conversión; en las escalas, 1 : n.|Error absolut = |real − aproximat|; error relatiu = error absolut ÷ real. Per a canviar d’unitats usa factors de conversió; en les escales, 1 : n.|Absolute error = |true − approximate|; relative error = absolute error ÷ true value. To change units use conversion factors; on scales, 1 : n.'.replace(/\|real − aproximado\|/, '∣real − aproximado∣').replace(/\|real − aproximat\|/, '∣real − aproximat∣').replace(/\|true − approximate\|/, '∣true − approximate∣')],
  'Mido 9,8 m y la medida real es 10 m. ¿Error relativo?|Mesure 9,8 m i la mesura real és 10 m. Error relatiu?|I measure 9.8 m and the true length is 10 m. Relative error?', ['Error absoluto: 0,2 m.|Error absolut: 0,2 m.|Absolute error: 0.2 m.', '0,2 / 10 = 0,02 = 2 %.|0,2 / 10 = 0,02 = 2 %.|0.2 ÷ 10 = 0.02 = 2%.'], mix(absRelError(), scale(), areaUnits()));
export const anglesRad = G(['Los ángulos se miden en grados o en radianes: 180° = π rad. Para pasar de grados a radianes, multiplica por π/180.|Els angles es mesuren en graus o en radians: 180° = π rad. Per a passar de graus a radians, multiplica per π/180.|Angles are measured in degrees or radians: 180° = π rad. To convert degrees to radians, multiply by π/180.'],
  '¿Cuántos grados son 3π/4 rad?|Quants graus són 3π/4 rad?|How many degrees is 3π/4 rad?', ['π = 180°.|π = 180°.|π = 180°.', '3 · 180 / 4 = 135°.|3 · 180 / 4 = 135°.|3 × 180 ÷ 4 = 135°.'], radians());
export const moves = G(['Traslación: suma un vector. Simetría respecto al eje X: (x, −y); respecto al eje Y: (−x, y). Giro de 180° con centro en el origen: (−x, −y).|Translació: suma un vector. Simetria respecte a l’eix X: (x, −y); respecte a l’eix Y: (−x, y). Gir de 180° amb centre en l’origen: (−x, −y).|Translation: add a vector. Reflection in the x-axis: (x, −y); in the y-axis: (−x, y). Rotation of 180° about the origin: (−x, −y).'],
  'Traslada (2, −1) con el vector (−3, 4).|Trasllada (2, −1) amb el vector (−3, 4).|Translate (2, −1) by the vector (−3, 4).', ['(2 − 3, −1 + 4).|(2 − 3, −1 + 4).|(2 − 3, −1 + 4).', '(−1, 3).|(−1, 3).|(−1, 3).'], transform());
export const pythTriangle = G(['Pitágoras relaciona los lados del triángulo rectángulo. Sirve para alturas de triángulos, diagonales de prismas y distancias entre puntos.|Pitàgores relaciona els costats del triangle rectangle. Servix per a altures de triangles, diagonals de prismes i distàncies entre punts.|Pythagoras links the sides of a right-angled triangle. It gives triangle heights, diagonals of boxes and distances between points.', 'Distancia entre (x₁, y₁) y (x₂, y₂): √((x₂ − x₁)² + (y₂ − y₁)²).|Distància entre (x₁, y₁) i (x₂, y₂): √((x₂ − x₁)² + (y₂ − y₁)²).|Distance between (x₁, y₁) and (x₂, y₂): √((x₂ − x₁)² + (y₂ − y₁)²).'],
  'Distancia entre (1, 1) y (4, 5).|Distància entre (1, 1) i (4, 5).|Distance between (1, 1) and (4, 5).', ['Diferencias: 3 y 4.|Diferències: 3 i 4.|Differences: 3 and 4.', '√(9 + 16) = 5.|√(9 + 16) = 5.|√(9 + 16) = 5.'], mix(pythagoras(), vectorsLines(['mod']), (r) => { const [a, b, c] = [[3, 4, 5], [6, 8, 10], [5, 12, 13]][Math.floor(r() * 3)]; const x = Math.floor(r() * 5) - 2, y = Math.floor(r() * 5) - 2;
    return Nq(`¿Cuál es la distancia entre los puntos (${x}, ${y}) y (${x + a}, ${y + b})?|Quina és la distància entre els punts (${x}, ${y}) i (${x + a}, ${y + b})?|What is the distance between the points (${x}, ${y}) and (${x + a}, ${y + b})?`, c, [a + b, c + 1, Math.abs(a - b) + c], 'Resta coordenadas y aplica Pitágoras.|Resta coordenades i aplica Pitàgores.|Subtract the coordinates and use Pythagoras.'); }));
export const trigRatios = G(['En un triángulo rectángulo: sen α = opuesto/hipotenusa; cos α = contiguo/hipotenusa; tg α = opuesto/contiguo. Sirven para calcular alturas y distancias inaccesibles.|En un triangle rectangle: sin α = oposat/hipotenusa; cos α = contigu/hipotenusa; tg α = oposat/contigu. Servixen per a calcular altures i distàncies inaccessibles.|In a right-angled triangle: sin α = opposite/hypotenuse; cos α = adjacent/hypotenuse; tan α = opposite/adjacent. They let us find heights and distances we cannot reach.'],
  'Triángulo 3-4-5. ¿tg del ángulo opuesto al lado 3?|Triangle 3-4-5. tg de l’angle oposat al costat 3?|Triangle 3-4-5. tan of the angle opposite side 3?', ['Opuesto 3, contiguo 4.|Oposat 3, contigu 4.|Opposite 3, adjacent 4.', 'tg = 3/4.|tg = 3/4.|tan = 3/4.'], mix(trig(), trigSolve()));
export const trigFull = G(['Relación fundamental: sen²α + cos²α = 1. Además tg α = sen α / cos α. Valores clave: sen 30° = 1/2, cos 60° = 1/2, tg 45° = 1.|Relació fonamental: sin²α + cos²α = 1. A més tg α = sin α / cos α. Valors clau: sin 30° = 1/2, cos 60° = 1/2, tg 45° = 1.|Key identity: sin²α + cos²α = 1. Also tan α = sin α ÷ cos α. Key values: sin 30° = 1/2, cos 60° = 1/2, tan 45° = 1.'],
  'Si sen α = 3/5 (α agudo), ¿cos α?|Si sin α = 3/5 (α agut), cos α?|If sin α = 3/5 (α acute), what is cos α?', ['cos²α = 1 − 9/25 = 16/25.|cos²α = 1 − 9/25 = 16/25.|cos²α = 1 − 9/25 = 16/25.', 'cos α = 4/5.|cos α = 4/5.|cos α = 4/5.'], mix(trig(), trigSolve(), radians()));
export const areasVolumes = G(['Áreas: suma de todas las caras o superficies. Volúmenes: prisma y cilindro, base × altura; pirámide y cono, base × altura / 3; esfera, 4/3 · πr³.|Àrees: suma de totes les cares o superfícies. Volums: prisma i cilindre, base × altura; piràmide i con, base × altura / 3; esfera, 4/3 · πr³.|Areas: add all the faces or surfaces. Volumes: prism and cylinder, base × height; pyramid and cone, base × height ÷ 3; sphere, 4/3 × πr³.'],
  'Cono de radio 3 cm y altura 4 cm: ¿volumen? (π ≈ 3,14)|Con de radi 3 cm i altura 4 cm: volum? (π ≈ 3,14)|Cone, radius 3 cm, height 4 cm: volume? (π ≈ 3.14)', ['Base: 3,14 · 9 = 28,26.|Base: 3,14 · 9 = 28,26.|Base: 3.14 × 9 = 28.26.', '28,26 · 4 / 3 = 37,68 cm³.|28,26 · 4 / 3 = 37,68 cm³.|28.26 × 4 ÷ 3 = 37.68 cm³.'], solids(['prismV', 'cylV', 'coneV', 'pyrV', 'sphV', 'cubeA', 'cylA']));
export const sphereGeo = lesson(['La Tierra es casi una esfera. Los paralelos son círculos paralelos al ecuador; la latitud mide el ángulo al norte o al sur (0° a 90°). Los meridianos van de polo a polo; la longitud mide el ángulo al este u oeste de Greenwich (0° a 180°).|La Terra és quasi una esfera. Els paral·lels són cercles paral·lels a l’equador; la latitud mesura l’angle al nord o al sud (0° a 90°). Els meridians van de pol a pol; la longitud mesura l’angle a l’est o l’oest de Greenwich (0° a 180°).|The Earth is almost a sphere. Parallels are circles parallel to the equator; latitude is the angle north or south (0° to 90°). Meridians run pole to pole; longitude is the angle east or west of Greenwich (0° to 180°).', 'Área de la esfera: 4πr². Volumen: 4/3 · πr³.|Àrea de l’esfera: 4πr². Volum: 4/3 · πr³.|Sphere area: 4πr². Volume: 4/3 × πr³.'],
  'València está a unos 39° N y 0° 22′ O. ¿Qué indica 39° N?|València està a uns 39° N i 0° 22′ O. Què indica 39° N?|Valencia is at about 39° N, 0° 22′ W. What does 39° N mean?', ['N es norte: hemisferio norte.|N és nord: hemisferi nord.|N is north: northern hemisphere.', 'Es la latitud: 39° al norte del ecuador.|És la latitud: 39° al nord de l’equador.|It is the latitude: 39° north of the equator.'], [
    M('¿Qué latitud tiene el ecuador?|Quina latitud té l’equador?|What is the latitude of the equator?', '0°|0°|0°', ['90°|90°|90°', '180°|180°|180°'], 'Es el punto de partida de la latitud.|És el punt de partida de la latitud.|Latitude starts from it.'),
    M('¿Qué latitud tiene el polo norte?|Quina latitud té el pol nord?|What is the latitude of the North Pole?', '90° N|90° N|90° N', ['0°|0°|0°', '180° N|180° N|180° N'], 'Es lo más lejos del ecuador.|És el més lluny de l’equador.|It is as far from the equator as possible.'),
    M('El meridiano de Greenwich tiene longitud…|El meridià de Greenwich té longitud…|The Greenwich meridian has longitude…', '0°|0°|0°', ['90°|90°|90°', '180°|180°|180°'], 'Es el meridiano de referencia.|És el meridià de referència.|It is the reference meridian.'),
    M('Las líneas que van de polo a polo son…|Les línies que van de pol a pol són…|Lines running from pole to pole are…', 'meridianos|meridians|meridians', ['paralelos|paral·lels|parallels', 'trópicos|tròpics|tropics'], 'Marcan la longitud.|Marquen la longitud.|They mark longitude.'),
    { q: L('Área de una esfera de radio 10 cm (π ≈ 3,14), en cm².|Àrea d’una esfera de radi 10 cm (π ≈ 3,14), en cm².|Surface area of a sphere with radius 10 cm (π ≈ 3.14), in cm².'), a: 1256, wrong: [314, 4186.67, 628], hint: L('4 · π · r².|4 · π · r².|4 × π × r².') },
    TF('Dos puntos en el mismo meridiano tienen la misma longitud.|Dos punts en el mateix meridià tenen la mateixa longitud.|Two points on the same meridian have the same longitude.', true, 'Cada meridiano es una longitud.|Cada meridià és una longitud.|Each meridian is one longitude.'),
  ]);
export const vectorsAndLines = G(['Un vector va de A a B: AB = (x₂ − x₁, y₂ − y₁). Su módulo es su longitud. Una recta: y = mx + n; rectas paralelas tienen igual pendiente.|Un vector va d’A a B: AB = (x₂ − x₁, y₂ − y₁). El seu mòdul és la seua longitud. Una recta: y = mx + n; rectes paral·leles tenen el mateix pendent.|A vector goes from A to B: AB = (x₂ − x₁, y₂ − y₁). Its magnitude is its length. A line: y = mx + c; parallel lines have equal gradients.'],
  'Vector de A(1, 2) a B(4, 6) y su módulo.|Vector d’A(1, 2) a B(4, 6) i el seu mòdul.|Vector from A(1, 2) to B(4, 6) and its magnitude.', ['(4 − 1, 6 − 2) = (3, 4).|(4 − 1, 6 − 2) = (3, 4).|(4 − 1, 6 − 2) = (3, 4).', '√(9 + 16) = 5.|√(9 + 16) = 5.|√(9 + 16) = 5.'], vectorsLines(['vec', 'mod', 'slope', 'eq', 'parallel']));
export const vectorsOnly = G(['Un vector tiene módulo (longitud), dirección y sentido. Se suman coordenada a coordenada y se multiplican por un número multiplicando cada coordenada.|Un vector té mòdul (longitud), direcció i sentit. Se sumen coordenada a coordenada i es multipliquen per un nombre multiplicant cada coordenada.|A vector has magnitude (length) and direction. Add vectors coordinate by coordinate; multiply by a number by multiplying each coordinate.'],
  '(2, −1) + 3 · (1, 2) = ?|(2, −1) + 3 · (1, 2) = ?|(2, −1) + 3 × (1, 2) = ?', ['3 · (1, 2) = (3, 6).|3 · (1, 2) = (3, 6).|3 × (1, 2) = (3, 6).', '(5, 5).|(5, 5).|(5, 5).'], mix(vectorsLines(['vec', 'mod']), (r) => { const a = Math.floor(r() * 7) - 3, b = Math.floor(r() * 7) - 3, c = Math.floor(r() * 5) - 2, d = Math.floor(r() * 5) - 2, k = 2 + Math.floor(r() * 2); const ans = `(${a + k * c}, ${b + k * d})`;
    return q(L(`(${a}, ${b}) + ${k} · (${c}, ${d}) = ?|(${a}, ${b}) + ${k} · (${c}, ${d}) = ?|(${a}, ${b}) + ${k} × (${c}, ${d}) = ?`), L(`${ans}|${ans}|${ans}`), [L(`(${a + c}, ${b + d})|(${a + c}, ${b + d})|(${a + c}, ${b + d})`), L(`(${k * (a + c)}, ${k * (b + d)})|(${k * (a + c)}, ${k * (b + d)})|(${k * (a + c)}, ${k * (b + d)})`), L(`(${a + k * c}, ${b - k * d})|(${a + k * c}, ${b - k * d})|(${a + k * c}, ${b - k * d})`)], L(`Primero multiplica (${c}, ${d}) por ${k}; después suma coordenada a coordenada.|Primer multiplica (${c}, ${d}) per ${k}; després suma coordenada a coordenada.|First multiply (${c}, ${d}) by ${k}; then add coordinate by coordinate.`)); }));
export const lineEquations = G(['Ecuaciones de la recta: explícita y = mx + n; punto-pendiente y − y₁ = m(x − x₁); general Ax + By + C = 0. Con dos puntos, calcula m y después n.|Equacions de la recta: explícita y = mx + n; punt-pendent y − y₁ = m(x − x₁); general Ax + By + C = 0. Amb dos punts, calcula m i després n.|Line equations: y = mx + c; point–gradient y − y₁ = m(x − x₁); general Ax + By + C = 0. With two points, find m then c.'],
  'Recta por (0, 1) y (2, 7).|Recta per (0, 1) i (2, 7).|Line through (0, 1) and (2, 7).', ['m = (7 − 1)/2 = 3.|m = (7 − 1)/2 = 3.|m = (7 − 1) ÷ 2 = 3.', 'Corta en y = 1: y = 3x + 1.|Talla en y = 1: y = 3x + 1.|It crosses at y = 1: y = 3x + 1.'], vectorsLines(['slope', 'eq', 'parallel']));
export const geoContext = G(['La geometría resuelve problemas reales: pintar una pared, llenar una piscina, medir un árbol con su sombra o calcular la diagonal de una pantalla.|La geometria resol problemes reals: pintar una paret, omplir una piscina, mesurar un arbre amb la seua ombra o calcular la diagonal d’una pantalla.|Geometry solves real problems: painting a wall, filling a pool, measuring a tree by its shadow or finding a screen’s diagonal.'],
  'Una piscina de 10 × 5 × 2 m. ¿Cuántos litros caben?|Una piscina de 10 × 5 × 2 m. Quants litres hi caben?|A 10 × 5 × 2 m pool. How many litres does it hold?', ['V = 100 m³.|V = 100 m³.|V = 100 m³.', '1 m³ = 1 000 L → 100 000 L.|1 m³ = 1 000 L → 100 000 L.|1 m³ = 1,000 L → 100,000 L.'], mix(compositeArea(), circle(['area', 'len']), pythagoras(), solids(['prismV', 'cylV'])));
export const varsFunctions = G(['Una función relaciona dos variables: a cada x le corresponde un único y. Se estudia su dominio, recorrido, crecimiento, máximos y mínimos y cortes con los ejes.|Una funció relaciona dues variables: a cada x li correspon un únic y. S’estudia el seu domini, recorregut, creixement, màxims i mínims i talls amb els eixos.|A function links two variables: each x gives exactly one y. We study its domain, range, where it increases, maxima and minima, and where it crosses the axes.'],
  'f(x) = x² − 1. ¿f(3)?|f(x) = x² − 1. f(3)?|f(x) = x² − 1. f(3)?', ['3² = 9.|3² = 9.|3² = 9.', '9 − 1 = 8.|9 − 1 = 8.|9 − 1 = 8.'], mix(graphRead(), linearFn(['eval']), quadraticFn()));
export const linearFns = G(['La función lineal y = mx + n: m es la pendiente, n la ordenada en el origen. Su gráfica es una recta. Si n = 0, es de proporcionalidad directa.|La funció lineal y = mx + n: m és el pendent, n l’ordenada en l’origen. La seua gràfica és una recta. Si n = 0, és de proporcionalitat directa.|The linear function y = mx + c: m is the gradient and c the y-intercept. Its graph is a straight line. If c = 0, it is direct proportion.'],
  'Un taxi cobra 3 € de bajada de bandera y 1,5 € por km. ¿Función?|Un taxi cobra 3 € de baixada de bandera i 1,5 € per km. Funció?|A taxi charges €3 to start and €1.50 per km. Function?', ['Fijo: 3. Por km: 1,5.|Fix: 3. Per km: 1,5.|Fixed: 3. Per km: 1.5.', 'y = 1,5x + 3.|y = 1,5x + 3.|y = 1.5x + 3.'], linearFn(['eval', 'slope', 'intercept', 'fromTable', 'zero']));
export const nonLinear = G(['Funciones no lineales: cuadráticas (parábolas, y = ax² + bx + c), de proporcionalidad inversa (hipérbolas, y = k/x) y exponenciales (y = a · bˣ, crecen o decrecen muy deprisa).|Funcions no lineals: quadràtiques (paràboles, y = ax² + bx + c), de proporcionalitat inversa (hipèrboles, y = k/x) i exponencials (y = a · bˣ, creixen o decreixen molt de pressa).|Non-linear functions: quadratics (parabolas, y = ax² + bx + c), inverse proportion (hyperbolas, y = k/x) and exponentials (y = a × bˣ, which grow or shrink very fast).'],
  'y = x² − 6x + 5. ¿Vértice?|y = x² − 6x + 5. Vèrtex?|y = x² − 6x + 5. Vertex?', ['x = −b/2a = 3.|x = −b/2a = 3.|x = −b ÷ 2a = 3.', 'y = 9 − 18 + 5 = −4 → (3, −4).|y = 9 − 18 + 5 = −4 → (3, −4).|y = 9 − 18 + 5 = −4 → (3, −4).'], mix(quadraticFn(), expGrowth()));
export const modelling = G(['Modelizar es elegir la función que describe una situación: lineal si aumenta lo mismo cada vez; exponencial si se multiplica; cuadrática en trayectorias; inversa si una sube y la otra baja con producto constante.|Modelitzar és triar la funció que descriu una situació: lineal si augmenta el mateix cada vegada; exponencial si es multiplica; quadràtica en trajectòries; inversa si una puja i l’altra baixa amb producte constant.|Modelling means choosing the function that fits a situation: linear if it grows by the same amount; exponential if it multiplies; quadratic for trajectories; inverse if one rises as the other falls with a constant product.'],
  'Una población de 500 conejos se duplica cada año. ¿Modelo?|Una població de 500 conills es duplica cada any. Model?|A population of 500 rabbits doubles every year. Model?', ['Se multiplica por 2 cada año: exponencial.|Es multiplica per 2 cada any: exponencial.|It multiplies by 2 each year: exponential.', 'y = 500 · 2ˣ.|y = 500 · 2ˣ.|y = 500 × 2ˣ.'], mix(expGrowth(), linearFn(['eval', 'fromTable'])));
export const sampleSpace = G(['El espacio muestral es el conjunto de resultados posibles. En experimentos compuestos se cuenta con tablas, árboles o el principio de multiplicación.|L’espai mostral és el conjunt de resultats possibles. En experiments compostos es compta amb taules, arbres o el principi de multiplicació.|The sample space is the set of possible outcomes. For combined experiments, count with tables, trees or the multiplication principle.'],
  'Lanzo 3 monedas. ¿Cuántos resultados?|Llance 3 monedes. Quants resultats?|I toss 3 coins. How many outcomes?', ['2 · 2 · 2.|2 · 2 · 2.|2 × 2 × 2.', '8.|8.|8.'], mix(compoundProb(), combinatorics()));
export const compound = G(['Diagrama de árbol: multiplica las probabilidades a lo largo de cada rama y suma las ramas que te interesan. Con o sin devolución cambia la segunda probabilidad.|Diagrama d’arbre: multiplica les probabilitats al llarg de cada branca i suma les branques que t’interessen. Amb o sense devolució canvia la segona probabilitat.|Tree diagram: multiply probabilities along each branch and add the branches you want. With or without replacement changes the second probability.'],
  'Bolsa con 4 rojas y 6 azules. Saco dos con devolución. ¿P(dos rojas)?|Bossa amb 4 roges i 6 blaves. En trac dues amb devolució. P(dues roges)?|Bag with 4 red and 6 blue. I take two with replacement. P(two red)?', ['4/10 · 4/10.|4/10 · 4/10.|4/10 × 4/10.', '= 16/100 = 4/25.|= 16/100 = 4/25.|= 16/100 = 4/25.'], compoundProb());
export const eventOperations = G(['Unión A ∪ B: pasa A o B. Intersección A ∩ B: pasan los dos. Contrario Ā: no pasa A. P(A ∪ B) = P(A) + P(B) − P(A ∩ B).|Unió A ∪ B: passa A o B. Intersecció A ∩ B: passen tots dos. Contrari Ā: no passa A. P(A ∪ B) = P(A) + P(B) − P(A ∩ B).|Union A ∪ B: A or B happens. Intersection A ∩ B: both happen. Complement Ā: A does not happen. P(A ∪ B) = P(A) + P(B) − P(A ∩ B).'],
  'Dado: A = par, B = mayor que 4. ¿A ∩ B?|Dau: A = parell, B = major que 4. A ∩ B?|Dice: A = even, B = greater than 4. A ∩ B?', ['A = {2, 4, 6}; B = {5, 6}.|A = {2, 4, 6}; B = {5, 6}.|A = {2, 4, 6}; B = {5, 6}.', 'Común: {6}.|Comú: {6}.|In both: {6}.'], eventOps());
export const conditional = G(['Probabilidad condicionada P(A | B): la probabilidad de A sabiendo que ha pasado B. Se calcula mirando solo los casos de B: P(A | B) = P(A ∩ B) / P(B).|Probabilitat condicionada P(A | B): la probabilitat d’A sabent que ha passat B. Es calcula mirant només els casos de B: P(A | B) = P(A ∩ B) / P(B).|Conditional probability P(A | B): the probability of A given that B has happened. Look only at the B cases: P(A | B) = P(A ∩ B) ÷ P(B).'.replace(/P\(A \| B\)/g, 'P(A/B)')],
  'En una clase, 12 de 20 chicas hacen deporte. Elijo una chica. ¿P(hace deporte)?|En una classe, 12 de 20 xiques fan esport. Trie una xica. P(fa esport)?|In a class, 12 of 20 girls play sport. I pick a girl. P(plays sport)?', ['Solo cuentan las chicas: 20 casos.|Només compten les xiques: 20 casos.|Only the girls count: 20 cases.', '12/20 = 3/5.|12/20 = 3/5.|12/20 = 3/5.'], condProb());
export const largeNumbers = G(['Al repetir un experimento muchas veces, la frecuencia relativa se estabiliza cerca de la probabilidad. Por eso se puede estimar una probabilidad experimentando.|En repetir un experiment moltes vegades, la freqüència relativa s’estabilitza prop de la probabilitat. Per això es pot estimar una probabilitat experimentant.|When an experiment is repeated many times, the relative frequency settles near the probability. That is why we can estimate a probability by experimenting.'],
  'Una chincheta cae de punta 312 veces de 1 000. ¿P estimada?|Una xinxeta cau de punta 312 vegades de 1 000. P estimada?|A drawing pin lands point up 312 times out of 1,000. Estimated P?', ['312/1 000.|312/1 000.|312/1,000.', '≈ 0,31.|≈ 0,31.|≈ 0.31.'], relFreq());
export const riskDecisions = lesson(['Para decidir con riesgo, calcula el valor esperado: suma de cada resultado por su probabilidad. Un juego es justo si el valor esperado es 0.|Per a decidir amb risc, calcula el valor esperat: suma de cada resultat per la seua probabilitat. Un joc és just si el valor esperat és 0.|To decide under risk, work out the expected value: the sum of each outcome times its probability. A game is fair if the expected value is 0.'],
  'Pago 1 € por lanzar un dado. Si sale 6 me dan 6 €. ¿Es justo?|Pague 1 € per llançar un dau. Si ix 6 em donen 6 €. És just?|I pay €1 to roll a dice. If I get a 6 I receive €6. Is it fair?', ['Ganancia media: 6 · 1/6 = 1 €.|Guany mitjà: 6 · 1/6 = 1 €.|Average win: 6 × 1/6 = €1.', '1 − 1 = 0: es justo.|1 − 1 = 0: és just.|1 − 1 = 0: it is fair.'], [
    { q: L('Juego: ganas 10 € con probabilidad 0,2 y pierdes 3 € con probabilidad 0,8. ¿Valor esperado (€)?|Joc: guanyes 10 € amb probabilitat 0,2 i perds 3 € amb probabilitat 0,8. Valor esperat (€)?|Game: win €10 with probability 0.2, lose €3 with probability 0.8. Expected value (€)?'), a: -0.4, wrong: [7, 0.4, 2], hint: L('10 · 0,2 − 3 · 0,8.|10 · 0,2 − 3 · 0,8.|10 × 0.2 − 3 × 0.8.') },
    TF('Si el valor esperado de un juego es negativo, a la larga pierdes dinero.|Si el valor esperat d’un joc és negatiu, a la llarga perds diners.|If a game’s expected value is negative, you lose money in the long run.', true, 'Es lo que pierdes de media en cada partida.|És el que perds de mitjana en cada partida.|It is what you lose on average each game.'),
    M('Un seguro cuesta 50 € al año y cubre un daño de 2 000 € con probabilidad 0,01. ¿Coste medio esperado del daño?|Una assegurança costa 50 € a l’any i cobrix un dany de 2 000 € amb probabilitat 0,01. Cost mitjà esperat del dany?|Insurance costs €50 a year and covers €2,000 of damage with probability 0.01. Expected cost of the damage?', '20 €|20 €|€20', ['50 €|50 €|€50', '2 000 €|2 000 €|€2,000'], '2 000 · 0,01.|2 000 · 0,01.|2,000 × 0.01.'),
    TF('Un juego justo tiene valor esperado 0.|Un joc just té valor esperat 0.|A fair game has an expected value of 0.', true, 'Ni ganas ni pierdes a la larga.|Ni guanyes ni perds a la llarga.|You neither win nor lose in the long run.'),
    M('En la lotería, el valor esperado de un billete es…|En la loteria, el valor esperat d’un bitllet és…|In a lottery, the expected value of a ticket is…', 'menor que lo que cuesta|menor que el que costa|less than what it costs', ['mayor que lo que cuesta|major que el que costa|more than what it costs', 'igual a lo que cuesta|igual al que costa|equal to what it costs'], 'Parte de lo recaudado no se reparte en premios.|Part del que es recapta no es reparteix en premis.|Part of the money raised is not paid out as prizes.'),
    M('Una prueba da positivo falso en el 2 % de casos sanos. Si 500 personas sanas se la hacen, ¿cuántos falsos positivos se esperan?|Una prova dona positiu fals en el 2 % de casos sans. Si 500 persones sanes se la fan, quants falsos positius s’esperen?|A test gives a false positive for 2% of healthy people. If 500 healthy people take it, how many false positives are expected?', '10|10|10', ['2|2|2', '50|50|50'], '2 % de 500.|2 % de 500.|2% of 500.'),
  ]);
export const designStudy = lesson(['Un estudio estadístico: plantear la pregunta, definir población y variables, elegir la muestra, recoger datos, organizarlos, analizarlos y sacar conclusiones con prudencia.|Un estudi estadístic: plantejar la pregunta, definir població i variables, triar la mostra, recollir dades, organitzar-les, analitzar-les i traure conclusions amb prudència.|A statistical study: set the question, define the population and variables, choose the sample, collect data, organise and analyse it, and draw careful conclusions.'],
  '¿Cuál es el primer paso de un estudio estadístico?|Quin és el primer pas d’un estudi estadístic?|What is the first step of a statistical study?', ['Antes de preguntar, hay que saber qué queremos averiguar.|Abans de preguntar, cal saber què volem esbrinar.|Before asking anything, we need to know what we want to find out.', 'Plantear la pregunta de investigación.|Plantejar la pregunta d’investigació.|Set the research question.'], [
    M('¿Qué pregunta de encuesta está mejor formulada?|Quina pregunta d’enquesta està millor formulada?|Which survey question is better worded?', '¿Cuántas horas duermes entre semana?|Quantes hores dorms entre setmana?|How many hours do you sleep on school nights?', ['¿Verdad que duermes poco?|Veritat que dorms poc?|You do not sleep much, do you?', '¿Duermes bien o mal o regular o depende?|Dorms bé o malament o regular o depén?|Do you sleep well or badly or OK or it depends?'], 'Clara, neutral y con respuesta concreta.|Clara, neutral i amb resposta concreta.|Clear, neutral and with a precise answer.'),
    M('¿Qué fase va después de recoger los datos?|Quina fase va després de recollir les dades?|Which step comes after collecting the data?', 'organizarlos en tablas y gráficos|organitzar-les en taules i gràfics|organising them in tables and charts', ['elegir la muestra|triar la mostra|choosing the sample', 'plantear la pregunta|plantejar la pregunta|setting the question'], 'Primero se ordenan, luego se analizan.|Primer s’ordenen, després s’analitzen.|First organise, then analyse.'),
    TF('Una pregunta como «¿Verdad que el deporte es lo mejor?» puede sesgar las respuestas.|Una pregunta com «Veritat que l’esport és el millor?» pot esbiaixar les respostes.|A question like "Isn’t sport the best thing?" can bias the answers.', true, 'Empuja hacia una respuesta.|Empeny cap a una resposta.|It pushes towards one answer.'),
    M('Si encuestas a 30 personas de una población de 900, la muestra es…|Si enquestes 30 persones d’una població de 900, la mostra és…|If you survey 30 people from a population of 900, the sample is…', 'las 30 personas|les 30 persones|the 30 people', ['las 900 personas|les 900 persones|the 900 people', 'la pregunta|la pregunta|the question'], 'La muestra es la parte que estudias.|La mostra és la part que estudies.|The sample is the part you study.'),
    M('Para estudiar el uso del móvil en un instituto con 4 cursos, lo mejor es…|Per a estudiar l’ús del mòbil en un institut amb 4 cursos, el millor és…|To study phone use in a school with 4 year groups, it is best to…', 'elegir al azar alumnado de cada curso|triar a l’atzar alumnat de cada curs|pick pupils at random from each year', ['preguntar solo a 4.º|preguntar només a 4t|ask only Year 10', 'preguntar a tus amigos|preguntar als teus amics|ask your friends'], 'Muestreo estratificado.|Mostreig estratificat.|Stratified sampling.'),
    TF('Si en la muestra la media es 7,2 horas, la de toda la población será exactamente 7,2.|Si en la mostra la mitjana és 7,2 hores, la de tota la població serà exactament 7,2.|If the sample mean is 7.2 hours, the population mean will be exactly 7.2.', false, 'Será parecida, no exacta.|Serà semblant, no exacta.|It will be similar, not exact.'),
  ]);
export const sheetsCharts = G(['Con una hoja de cálculo: =PROMEDIO, =MEDIANA, =MODA, =DESVEST y =CONTAR.SI calculan al momento. Elige el gráfico según la variable: barras o sectores (cualitativas), histograma (continuas agrupadas).|Amb un full de càlcul: =MITJANA, =MEDIANA, =MODA, =DESVEST i =COMPTA.SI calculen al moment. Tria el gràfic segons la variable: barres o sectors (qualitatives), histograma (contínues agrupades).|With a spreadsheet: =AVERAGE, =MEDIAN, =MODE, =STDEV and =COUNTIF work things out instantly. Choose the chart by variable: bar or pie (categorical), histogram (grouped continuous).'],
  'Para datos de alturas agrupados en intervalos, ¿qué gráfico?|Per a dades d’altures agrupades en intervals, quin gràfic?|For heights grouped into intervals, which chart?', ['La altura es continua y está agrupada.|L’altura és contínua i està agrupada.|Height is continuous and grouped.', 'Histograma.|Histograma.|Histogram.'], mix(histogram(), pieChart()));
export const dispersion = G(['Rango: máximo − mínimo. Varianza: media de los cuadrados de las desviaciones. Desviación típica: √varianza. Cuanto mayor, más dispersos están los datos.|Rang: màxim − mínim. Variància: mitjana dels quadrats de les desviacions. Desviació típica: √variància. Com més gran, més disperses estan les dades.|Range: max − min. Variance: mean of the squared deviations. Standard deviation: √variance. The larger it is, the more spread out the data.'],
  'Datos: 2, 4, 6 (media 4). ¿Desviación típica?|Dades: 2, 4, 6 (mitjana 4). Desviació típica?|Data: 2, 4, 6 (mean 4). Standard deviation?', ['Varianza: (4 + 0 + 4)/3 ≈ 2,67.|Variància: (4 + 0 + 4)/3 ≈ 2,67.|Variance: (4 + 0 + 4) ÷ 3 ≈ 2.67.', '√2,67 ≈ 1,63.|√2,67 ≈ 1,63.|√2.67 ≈ 1.63.'], spread(['var', 'sd', 'range']));
export const coefVar = G(['El coeficiente de variación CV = desviación típica ÷ media (en %) permite comparar la dispersión de grupos con medias distintas.|El coeficient de variació CV = desviació típica ÷ mitjana (en %) permet comparar la dispersió de grups amb mitjanes diferents.|The coefficient of variation CV = standard deviation ÷ mean (as a %) compares spread between groups with different means.'],
  'Grupo A: media 50, σ = 5. Grupo B: media 10, σ = 2. ¿Cuál es más disperso?|Grup A: mitjana 50, σ = 5. Grup B: mitjana 10, σ = 2. Quin és més dispers?|Group A: mean 50, σ = 5. Group B: mean 10, σ = 2. Which is more spread out?', ['CV A = 10 %; CV B = 20 %.|CV A = 10 %; CV B = 20 %.|CV A = 10%; CV B = 20%.', 'B es más disperso en proporción.|B és més dispers en proporció.|B is more spread out relative to its mean.'], spread(['cv', 'sd']));
export const scatterCorr = lesson(['Un diagrama de dispersión dibuja parejas de datos (x, y). Si los puntos suben juntos, hay correlación positiva; si una sube y la otra baja, negativa; si no hay forma, no hay correlación. Correlación no es causa.|Un diagrama de dispersió dibuixa parelles de dades (x, y). Si els punts pugen junts, hi ha correlació positiva; si una puja i l’altra baixa, negativa; si no hi ha forma, no hi ha correlació. Correlació no és causa.|A scatter graph plots pairs of data (x, y). If the points rise together, there is positive correlation; if one rises as the other falls, negative; if there is no pattern, no correlation. Correlation is not causation.'],
  'Horas de estudio y nota suben juntas. ¿Correlación?|Hores d’estudi i nota pugen juntes. Correlació?|Study hours and marks rise together. Correlation?', ['Cuando una aumenta, la otra también.|Quan una augmenta, l’altra també.|When one increases, so does the other.', 'Positiva.|Positiva.|Positive.'], [
    M('Temperatura exterior y gasto en calefacción. Correlación…|Temperatura exterior i despesa en calefacció. Correlació…|Outdoor temperature and heating costs. Correlation…', 'negativa|negativa|negative', ['positiva|positiva|positive', 'nula|nul·la|none'], 'Más calor, menos calefacción.|Més calor, menys calefacció.|Warmer means less heating.'),
    M('Número de calzado y nota de matemáticas. Correlación…|Número de calçat i nota de matemàtiques. Correlació…|Shoe size and maths mark. Correlation…', 'nula|nul·la|none', ['positiva|positiva|positive', 'negativa|negativa|negative'], 'No tienen relación.|No tenen relació.|They are unrelated.'),
    M('Altura y peso de un grupo de personas. Correlación…|Altura i pes d’un grup de persones. Correlació…|Height and weight of a group of people. Correlation…', 'positiva|positiva|positive', ['negativa|negativa|negative', 'nula|nul·la|none'], 'En general, más altura, más peso.|En general, més altura, més pes.|In general, taller people weigh more.'),
    TF('Si dos variables tienen correlación fuerte, una es siempre la causa de la otra.|Si dues variables tenen correlació forta, una és sempre la causa de l’altra.|If two variables are strongly correlated, one always causes the other.', false, 'Puede haber una tercera causa común (venta de helados y quemaduras: el calor).|Pot haver-hi una tercera causa comuna (venda de gelats i cremades: la calor).|There may be a common cause (ice-cream sales and sunburn: hot weather).'),
    M('r = −0,95 indica una correlación…|r = −0,95 indica una correlació…|r = −0.95 shows a correlation that is…', 'fuerte y negativa|forta i negativa|strong and negative', ['débil y negativa|feble i negativa|weak and negative', 'fuerte y positiva|forta i positiva|strong and positive'], 'Cerca de −1.|Prop de −1.|Close to −1.'),
    M('En un diagrama de dispersión, los puntos forman una nube redonda sin dirección. La correlación es…|En un diagrama de dispersió, els punts formen un núvol redó sense direcció. La correlació és…|On a scatter graph, the points form a round cloud with no direction. The correlation is…', 'casi nula|quasi nul·la|close to zero', ['fuerte|forta|strong', 'perfecta|perfecta|perfect'], 'No hay tendencia.|No hi ha tendència.|There is no trend.'),
  ]);
export const regressionL = G(['La recta de regresión es la recta que mejor se ajusta a la nube de puntos. Una hoja de cálculo o GeoGebra la calcula. Sirve para predecir, con prudencia y solo dentro del rango de los datos.|La recta de regressió és la recta que millor s’ajusta al núvol de punts. Un full de càlcul o GeoGebra la calcula. Servix per a predir, amb prudència i només dins del rang de les dades.|The regression line is the line that best fits the scatter of points. A spreadsheet or GeoGebra works it out. It is used to predict, carefully and only within the range of the data.'],
  'Recta: y = 30 + 5x (x = horas, y = nota). ¿Predicción para 8 h?|Recta: y = 30 + 5x (x = hores, y = nota). Predicció per a 8 h?|Line: y = 30 + 5x (x = hours, y = mark). Prediction for 8 h?', ['y = 30 + 5 · 8.|y = 30 + 5 · 8.|y = 30 + 5 × 8.', '70.|70.|70.'], regression());
export const interpretStudies = lesson(['Al leer un estudio, comprueba: ¿quién lo hizo?, ¿tamaño y tipo de muestra?, ¿qué medida se da (media o mediana)?, ¿el gráfico empieza en 0?, ¿se confunde correlación con causa?|En llegir un estudi, comprova: qui el va fer?, mida i tipus de mostra?, quina mesura es dona (mitjana o mediana)?, el gràfic comença en 0?, es confon correlació amb causa?|When reading a study, check: who did it? sample size and type? which measure is given (mean or median)? does the chart start at 0? is correlation confused with causation?'],
  'Un anuncio dice: «9 de cada 10 dentistas lo recomiendan» tras preguntar a 10. ¿Es fiable?|Un anunci diu: «9 de cada 10 dentistes el recomanen» després de preguntar-ne 10. És fiable?|An advert says "9 out of 10 dentists recommend it" after asking 10. Is it reliable?', ['La muestra es muy pequeña.|La mostra és molt xicoteta.|The sample is very small.', 'No sabemos cómo se eligieron: poco fiable.|No sabem com es van triar: poc fiable.|We do not know how they were chosen: not very reliable.'], [
    M('Un gráfico de barras empieza en 95 en vez de 0. Efecto:|Un gràfic de barres comença en 95 en lloc de 0. Efecte:|A bar chart starts at 95 instead of 0. Effect:', 'exagera las diferencias|exagera les diferències|it exaggerates the differences', ['las oculta|les amaga|it hides them', 'no cambia nada|no canvia res|nothing changes'], 'Las barras parecen muy distintas aunque no lo sean.|Les barres semblen molt diferents encara que no ho siguen.|The bars look very different even if they are not.'),
    M('Para salarios con unos pocos muy altos, ¿qué representa mejor lo habitual?|Per a salaris amb uns pocs molt alts, què representa millor l’habitual?|For salaries with a few very high ones, what best shows the typical value?', 'la mediana|la mediana|the median', ['la media|la mitjana|the mean', 'el máximo|el màxim|the maximum'], 'La media se dispara con valores extremos.|La mitjana es dispara amb valors extrems.|The mean is pulled up by extreme values.'),
    TF('Un estudio financiado por quien vende el producto merece revisarse con más cuidado.|Un estudi finançat per qui ven el producte mereix revisar-se amb més cura.|A study paid for by the seller of the product deserves extra scrutiny.', true, 'Puede haber conflicto de intereses.|Pot haver-hi conflicte d’interessos.|There may be a conflict of interest.'),
    M('«Los que desayunan sacan mejores notas, así que desayunar sube la nota.» El error es…|«Els que esmorzen trauen millors notes, així que esmorzar puja la nota.» L’error és…|"Those who eat breakfast get better marks, so breakfast raises marks." The mistake is…', 'confundir correlación con causa|confondre correlació amb causa|confusing correlation with causation', ['usar la mediana|usar la mediana|using the median', 'la muestra es grande|la mostra és gran|the sample is large'], 'Puede haber otros factores.|Hi pot haver altres factors.|There may be other factors.'),
    M('Una encuesta en una web de videojuegos dice que el 80 % juega a diario. Problema:|Una enquesta en una web de videojocs diu que el 80 % juga cada dia. Problema:|A survey on a video-game website says 80% play every day. Problem:', 'muestra sesgada|mostra esbiaixada|biased sample', ['muestra estratificada|mostra estratificada|stratified sample', 'ninguno|cap|none'], 'Solo responden los aficionados.|Només responen els aficionats.|Only fans answer.'),
    TF('Un porcentaje sin decir de cuántos casos se calculó puede engañar.|Un percentatge sense dir de quants casos es va calcular pot enganyar.|A percentage given without the number of cases can mislead.', true, '50 % de 2 no es lo mismo que 50 % de 2 000.|50 % de 2 no és el mateix que 50 % de 2 000.|50% of 2 is not the same as 50% of 2,000.'),
  ]);
export const algorithms = G(['Un algoritmo resuelve un problema paso a paso. Se diseña pensando en la entrada, el proceso (variables, bucles, condiciones) y la salida, y se prueba con ejemplos.|Un algorisme resol un problema pas a pas. Es dissenya pensant en l’entrada, el procés (variables, bucles, condicions) i l’eixida, i es prova amb exemples.|An algorithm solves a problem step by step. Design it around input, process (variables, loops, conditions) and output, and test it with examples.'],
  'n = 10. Mientras n > 1: si n es par, n = n/2; si no, n = 3n + 1. ¿Cuántos pasos?|n = 10. Mentre n > 1: si n és parell, n = n/2; si no, n = 3n + 1. Quants passos?|n = 10. While n > 1: if n is even, n = n/2; otherwise n = 3n + 1. How many steps?', ['10 → 5 → 16 → 8 → 4 → 2 → 1.|10 → 5 → 16 → 8 → 4 → 2 → 1.|10 → 5 → 16 → 8 → 4 → 2 → 1.', '6 pasos.|6 passos.|6 steps.'], mix(loops(), robot(6), (r) => { const start = [3, 5, 6, 7, 10, 12][Math.floor(r() * 6)]; let n = start, steps = 0; while (n > 1) { n = n % 2 ? 3 * n + 1 : n / 2; steps++; }
    return Nq(`n = ${start}. Mientras n > 1: si n es par, n = n/2; si no, n = 3n + 1. ¿Cuántos pasos hasta llegar a 1?|n = ${start}. Mentre n > 1: si n és parell, n = n/2; si no, n = 3n + 1. Quants passos fins a arribar a 1?|n = ${start}. While n > 1: if n is even, n = n/2; otherwise n = 3n + 1. How many steps until it reaches 1?`, steps, [steps - 1, steps + 1, steps + 2], 'Escribe cada valor de n en una lista.|Escriu cada valor de n en una llista.|Write each value of n in a list.'); }));
export const logicGames = G(['En los juegos de estrategia, analiza las posiciones desde el final: una posición es perdedora si cualquier jugada deja al otro en posición ganadora.|En els jocs d’estratègia, analitza les posicions des del final: una posició és perdedora si qualsevol jugada deixa l’altre en posició guanyadora.|In strategy games, analyse positions from the end: a position is losing if every move leaves the opponent in a winning one.'],
  'Se quitan de 1 a 4; gana quien quita la última. Hay 23. ¿Cuántas quitas?|Es lleven d’1 a 4; guanya qui lleva l’última. N’hi ha 23. Quantes en lleves?|You remove 1 to 4; whoever takes the last wins. There are 23. How many do you take?', ['Hay que dejar múltiplos de 5.|Cal deixar múltiples de 5.|Leave a multiple of 5.', 'Quito 3 y dejo 20.|Lleve 3 i en deixe 20.|Take 3 and leave 20.'], nim(40, [3, 4, 5]));
export type L4 = LessonContent;
export const combinatoricsL = G(['Combinatoria: contar sin enumerar. Permutaciones (ordenar n elementos): n!. Variaciones (elegir k de n importando el orden): n · (n − 1) · … (k factores). Combinaciones (sin importar el orden): variaciones ÷ k!.|Combinatòria: comptar sense enumerar. Permutacions (ordenar n elements): n!. Variacions (triar k de n i importa l’ordre): n · (n − 1) · … (k factors). Combinacions (no importa l’ordre): variacions ÷ k!.|Combinatorics: counting without listing. Permutations (ordering n items): n!. Arrangements (choosing k of n where order matters): n × (n − 1) × … (k factors). Combinations (order does not matter): arrangements ÷ k!.'],
  '¿Cuántas parejas distintas se pueden formar con 5 personas?|Quantes parelles diferents es poden formar amb 5 persones?|How many different pairs can be made from 5 people?', ['Con orden serían 5 · 4 = 20.|Amb ordre serien 5 · 4 = 20.|With order it would be 5 × 4 = 20.', 'Sin orden: 20 / 2 = 10.|Sense ordre: 20 / 2 = 10.|Without order: 20 ÷ 2 = 10.'], combinatorics());
